// GET handshake. The token comparison is the ENTIRE security of this endpoint.
// Echoing the challenge without checking it lets anyone on the internet
// subscribe their own Meta app to our URL.
const q = $input.first().json.query || {};
const expected = $env.META_VERIFY_TOKEN_SHALOM_PARK;

if (!expected) {
  return [{ json: { status: 500, body: 'META_VERIFY_TOKEN_SHALOM_PARK not set' } }];
}

const mode  = q['hub.mode'];
const token = q['hub.verify_token'];

// Constant-time-ish compare: equal length check first, then char accumulation.
let ok = typeof token === 'string' && token.length === expected.length;
if (ok) {
  let diff = 0;
  for (let i = 0; i < expected.length; i++) diff |= token.charCodeAt(i) ^ expected.charCodeAt(i);
  ok = diff === 0;
}

if (mode === 'subscribe' && ok) {
  return [{ json: { status: 200, body: String(q['hub.challenge'] ?? '') } }];
}
return [{ json: { status: 403, body: 'Forbidden' } }];

// POST intake. Two jobs, in this order:
//  1. Prove the payload came from Meta (HMAC over the RAW body).
//  2. Flatten it into the shape the ledger and the brain expect.
// Without step 1, anyone who learns this URL can inject fake buyer
// messages -- and those write straight into the commission ledger.
const crypto = require('crypto');
const item = $input.first().json;
const secret = $env.SHALOM_PARK_APP_SECRET;

const headers = item.headers || {};
const sigHeader = headers['x-hub-signature-256'] || '';
const raw = item.rawBody ?? item.body ?? '';
const rawStr = Buffer.isBuffer(raw) ? raw.toString('utf8') : (typeof raw === 'string' ? raw : JSON.stringify(raw));

if (!secret) {
  return [{ json: { status: 500, verified: false, reason: 'SHALOM_PARK_APP_SECRET not set' } }];
}

const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(rawStr, 'utf8').digest('hex');
let verified = false;
try {
  verified = crypto.timingSafeEqual(Buffer.from(sigHeader), Buffer.from(expected));
} catch (e) {
  verified = false; // length mismatch throws
}

if (!verified) {
  return [{ json: { status: 403, verified: false, reason: 'bad signature' } }];
}

let body;
try { body = typeof rawStr === 'string' ? JSON.parse(rawStr) : rawStr; } catch (e) { body = {}; }

const value   = body?.entry?.[0]?.changes?.[0]?.value;
const message = value?.messages?.[0];
const contact = value?.contacts?.[0];

// Status callbacks (delivered/read) arrive on the same webhook. ACK, ignore.
if (!message) {
  return [{ json: { status: 200, verified: true, event_type: 'NON_MESSAGE_EVENT' } }];
}

return [{
  json: {
    status: 200,
    verified: true,
    event_type: 'INBOUND_MESSAGE',
    client_id: 'shalom-park',
    channel: 'whatsapp',
    provider_message_id: message.id,
    contact_e164: message.from,
    contact_hash: crypto.createHash('sha256').update(String(message.from)).digest('hex'),
    buyer_name: contact?.profile?.name || 'Prospective buyer',
    message_type: message.type,
    text_body: message.text?.body || '',
    occurred_at: new Date(Number(message.timestamp) * 1000).toISOString(),
    phone_number_id: value?.metadata?.phone_number_id || ''
  }
}];
